#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];

        // Compute multipliers for column k (L entries below the diagonal).
        #pragma omp parallel for default(none) shared(A, N, k, pivot)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            A[static_cast<size_t>(i) * N + k] /= pivot;
        }

        // Update the trailing submatrix:
        // A[i][j] -= A[i][k] * A[k][j] for i,j > k
        #pragma omp parallel for collapse(2) default(none) shared(A, N, k)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            for (std::ptrdiff_t j = static_cast<std::ptrdiff_t>(k) + 1; j < static_cast<std::ptrdiff_t>(N); ++j) {
                A[static_cast<size_t>(i) * N + static_cast<size_t>(j)] -=
                    A[static_cast<size_t>(i) * N + k] * A[k * N + static_cast<size_t>(j)];
            }
        }
    }
}
